+void ApplicationMenu::setGtkMenuProxyAvailable(bool available)
+{
+    m_gtkMenuProxyAvailable = available;
+
+    // Like on X11, GTK applications hide their own menu bar only when the proxy can show it elsewhere
+    if (available) {
+        waylandServer()->gtkShell()->setCapabilities({GtkShellInterface::Capability::GlobalMenuBar});
+    } else {
+        waylandServer()->gtkShell()->setCapabilities({});
+    }
+
+    for (auto it = m_gtkMenus.cbegin(); it != m_gtkMenus.cend(); ++it) {
+        if (available) {
+            registerGtkMenuWithProxy(it.key(), it->properties);
+        } else if (it->window) {
+            it->window->setGtkApplicationMenu(QString(), QString());
+        }
+    }
+}
+
+void ApplicationMenu::registerGtkMenu(XdgToplevelWindow *window, const GtkSurfaceInterface::DBusProperties &properties)
+{
+    if (properties.uniqueBusName.isEmpty() || (properties.menuBarPath.isEmpty() && properties.appMenuPath.isEmpty())) {
+        unregisterGtkMenu(window);
+        return;
+    }
+
+    auto it = m_gtkMenus.find(window->internalId());
+    if (it != m_gtkMenus.end() && it->properties == properties) {
+        return;
+    }
+
+    m_gtkMenus.insert(window->internalId(), GtkMenu{window, properties});
+    if (m_gtkMenuProxyAvailable) {
+        registerGtkMenuWithProxy(window->internalId(), properties);
+    }
+}
+
+void ApplicationMenu::unregisterGtkMenu(XdgToplevelWindow *window)
+{
+    if (!m_gtkMenus.remove(window->internalId()) || !m_gtkMenuProxyAvailable) {
+        return;
+    }
+
+    QDBusMessage message = QDBusMessage::createMethodCall(s_gtkMenuProxyService, s_gtkMenuProxyPath, s_gtkMenuProxyInterface, QStringLiteral("UnregisterWindow"));
+    message << window->internalId().toString(QUuid::WithoutBraces);
+    QDBusConnection::sessionBus().asyncCall(message);
+}
+
+void ApplicationMenu::registerGtkMenuWithProxy(const QUuid &windowId, const GtkSurfaceInterface::DBusProperties &properties)
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(s_gtkMenuProxyService, s_gtkMenuProxyPath, s_gtkMenuProxyInterface, QStringLiteral("RegisterWindow"));
+    message << windowId.toString(QUuid::WithoutBraces) << properties.uniqueBusName << properties.applicationObjectPath << properties.windowObjectPath
+            << properties.appMenuPath << properties.menuBarPath;
+    QDBusConnection::sessionBus().asyncCall(message);
+}
+
+void ApplicationMenu::slotGtkMenuChanged(const QString &windowId, const QString &serviceName, const QString &objectPath)
+{
+    // The window might not be mapped yet, so it can't be looked up in the workspace
+    const auto it = m_gtkMenus.constFind(QUuid(windowId));
+    if (it != m_gtkMenus.cend() && it->window) {
+        it->window->setGtkApplicationMenu(serviceName, objectPath);
+    }
+}
