diff --git a/src/wayland/gtkshell.cpp b/src/wayland/gtkshell.cpp
new file mode 100644
index 0000000000..2acda2a155
--- /dev/null
+++ b/src/wayland/gtkshell.cpp
@@ -0,0 +1,180 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+#include "gtkshell.h"
+#include "display.h"
+#include "surface.h"
+
+#include <QPointer>
+
+#include "qwayland-server-gtk-shell.h"
+
+namespace KWin
+{
+
+// Only version 1: newer versions promise features (titlebar gestures, surface offsets) that we don't implement
+static const quint32 s_version = 1;
+
+class GtkShellInterfacePrivate : public QtWaylandServer::gtk_shell1
+{
+public:
+    GtkShellInterfacePrivate(GtkShellInterface *q, Display *display);
+
+    GtkShellInterface *q;
+    QList<GtkSurfaceInterface *> gtkSurfaces;
+    uint32_t capabilities = 0;
+
+protected:
+    void gtk_shell1_bind_resource(Resource *resource) override;
+    void gtk_shell1_get_gtk_surface(Resource *resource, uint32_t gtk_surface, wl_resource *surface) override;
+};
+
+class GtkSurfaceInterfacePrivate : public QtWaylandServer::gtk_surface1
+{
+public:
+    GtkSurfaceInterfacePrivate(GtkSurfaceInterface *q, SurfaceInterface *surface, wl_resource *resource);
+
+    GtkSurfaceInterface *q;
+    QPointer<SurfaceInterface> surface;
+    GtkSurfaceInterface::DBusProperties dbusProperties;
+
+protected:
+    void gtk_surface1_destroy_resource(Resource *resource) override;
+    void gtk_surface1_set_dbus_properties(Resource *resource,
+                                          const QString &application_id,
+                                          const QString &app_menu_path,
+                                          const QString &menubar_path,
+                                          const QString &window_object_path,
+                                          const QString &application_object_path,
+                                          const QString &unique_bus_name) override;
+};
+
+GtkShellInterfacePrivate::GtkShellInterfacePrivate(GtkShellInterface *_q, Display *display)
+    : QtWaylandServer::gtk_shell1(*display, s_version)
+    , q(_q)
+{
+}
+
+void GtkShellInterfacePrivate::gtk_shell1_bind_resource(Resource *resource)
+{
+    send_capabilities(resource->handle, capabilities);
+}
+
+void GtkShellInterfacePrivate::gtk_shell1_get_gtk_surface(Resource *resource, uint32_t gtk_surface, wl_resource *surface)
+{
+    SurfaceInterface *s = SurfaceInterface::get(surface);
+    if (!s) {
+        wl_resource_post_error(resource->handle, 0, "Invalid surface");
+        return;
+    }
+    wl_resource *gtkSurfaceResource = wl_resource_create(resource->client(), &gtk_surface1_interface, resource->version(), gtk_surface);
+    if (!gtkSurfaceResource) {
+        wl_client_post_no_memory(resource->client());
+        return;
+    }
+    auto gtkSurfaceInterface = new GtkSurfaceInterface(s, gtkSurfaceResource);
+
+    gtkSurfaces.append(gtkSurfaceInterface);
+    QObject::connect(gtkSurfaceInterface, &QObject::destroyed, q, [this, gtkSurfaceInterface]() {
+        gtkSurfaces.removeOne(gtkSurfaceInterface);
+    });
+    // gtk_surface1 has no destructor before version 4, so it can outlive its wl_surface
+    QObject::connect(s, &SurfaceInterface::aboutToBeDestroyed, gtkSurfaceInterface, [this, gtkSurfaceInterface]() {
+        gtkSurfaces.removeOne(gtkSurfaceInterface);
+    });
+    Q_EMIT q->gtkSurfaceCreated(gtkSurfaceInterface);
+}
+
+GtkSurfaceInterfacePrivate::GtkSurfaceInterfacePrivate(GtkSurfaceInterface *_q, SurfaceInterface *s, wl_resource *resource)
+    : QtWaylandServer::gtk_surface1(resource)
+    , q(_q)
+    , surface(s)
+{
+}
+
+void GtkSurfaceInterfacePrivate::gtk_surface1_destroy_resource(Resource *resource)
+{
+    delete q;
+}
+
+void GtkSurfaceInterfacePrivate::gtk_surface1_set_dbus_properties(Resource *resource,
+                                                                  const QString &application_id,
+                                                                  const QString &app_menu_path,
+                                                                  const QString &menubar_path,
+                                                                  const QString &window_object_path,
+                                                                  const QString &application_object_path,
+                                                                  const QString &unique_bus_name)
+{
+    dbusProperties = {
+        .applicationId = application_id,
+        .appMenuPath = app_menu_path,
+        .menuBarPath = menubar_path,
+        .windowObjectPath = window_object_path,
+        .applicationObjectPath = application_object_path,
+        .uniqueBusName = unique_bus_name,
+    };
+    Q_EMIT q->dbusPropertiesChanged();
+}
+
+GtkShellInterface::GtkShellInterface(Display *display, QObject *parent)
+    : QObject(parent)
+    , d(new GtkShellInterfacePrivate(this, display))
+{
+}
+
+GtkShellInterface::~GtkShellInterface()
+{
+}
+
+GtkSurfaceInterface *GtkShellInterface::gtkSurfaceForSurface(SurfaceInterface *surface) const
+{
+    for (GtkSurfaceInterface *gtkSurface : std::as_const(d->gtkSurfaces)) {
+        if (gtkSurface->surface() == surface) {
+            return gtkSurface;
+        }
+    }
+    return nullptr;
+}
+
+void GtkShellInterface::setCapabilities(const QList<Capability> &capabilities)
+{
+    uint32_t bits = 0;
+    for (Capability capability : capabilities) {
+        bits |= 1 << (uint32_t(capability) - 1);
+    }
+    if (d->capabilities == bits) {
+        return;
+    }
+    d->capabilities = bits;
+
+    const auto resources = d->resourceMap();
+    for (GtkShellInterfacePrivate::Resource *resource : resources) {
+        d->send_capabilities(resource->handle, bits);
+    }
+}
+
+GtkSurfaceInterface::GtkSurfaceInterface(SurfaceInterface *surface, wl_resource *resource)
+    : QObject()
+    , d(new GtkSurfaceInterfacePrivate(this, surface, resource))
+{
+}
+
+GtkSurfaceInterface::~GtkSurfaceInterface()
+{
+}
+
+SurfaceInterface *GtkSurfaceInterface::surface() const
+{
+    return d->surface.data();
+}
+
+GtkSurfaceInterface::DBusProperties GtkSurfaceInterface::dbusProperties() const
+{
+    return d->dbusProperties;
+}
+
+} // namespace
+
+#include "moc_gtkshell.cpp"
