+#pragma once
+
+#include "kwin_export.h"
+
+#include <QObject>
+#include <memory>
+
+struct wl_resource;
+
+namespace KWin
+{
+
+class Display;
+class SurfaceInterface;
+class GtkSurfaceInterface;
+class GtkShellInterfacePrivate;
+class GtkSurfaceInterfacePrivate;
+
+/**
+ * Implements the parts of GTK's gtk_shell1 protocol that are needed to find the
+ * D-Bus menus a GTK application exports for its windows.
+ */
+class KWIN_EXPORT GtkShellInterface : public QObject
+{
+    Q_OBJECT
+
+public:
+    enum class Capability {
+        GlobalAppMenu = 1,
+        GlobalMenuBar = 2,
+        DesktopIcons = 3,
+    };
+
+    explicit GtkShellInterface(Display *display, QObject *parent = nullptr);
+    ~GtkShellInterface() override;
+
+    GtkSurfaceInterface *gtkSurfaceForSurface(SurfaceInterface *surface) const;
+
+    void setCapabilities(const QList<Capability> &capabilities);
+
+Q_SIGNALS:
+    void gtkSurfaceCreated(KWin::GtkSurfaceInterface *gtkSurface);
+
+private:
+    std::unique_ptr<GtkShellInterfacePrivate> d;
+};
+
+class KWIN_EXPORT GtkSurfaceInterface : public QObject
+{
+    Q_OBJECT
+
+public:
+    struct DBusProperties
+    {
+        QString applicationId;
+        QString appMenuPath;
+        QString menuBarPath;
+        QString windowObjectPath;
+        QString applicationObjectPath;
+        QString uniqueBusName;
+
+        bool operator==(const DBusProperties &other) const = default;
+    };
+
+    ~GtkSurfaceInterface() override;
+
+    SurfaceInterface *surface() const;
+    DBusProperties dbusProperties() const;
+
+Q_SIGNALS:
+    void dbusPropertiesChanged();
+
+private:
+    GtkSurfaceInterface(SurfaceInterface *surface, wl_resource *resource);
+    friend class GtkShellInterfacePrivate;
+
+    std::unique_ptr<GtkSurfaceInterfacePrivate> d;
+};
+
+}
